INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A media company hosts a critical web application that experiences fluctuating traffic. They require the application to be highly available across multiple Availability Zones and automatically scale compute resources to meet demand, while minimizing manual intervention. The application uses a relational database.', '["Deploy Amazon EC2 instances within an Auto Scaling group across multiple Availability Zones, fronted by an Application Load Balancer, and use Amazon RDS Multi-AZ for the database.","Deploy Amazon EC2 instances in a single Availability Zone with a manual scaling policy, use an Application Load Balancer, and an Amazon RDS database in a single Availability Zone.","Deploy Amazon EC2 instances in a single Availability Zone behind an Application Load Balancer, and use Amazon Aurora with a single instance for the database.","Manually provision Amazon EC2 instances across multiple Availability Zones, configure a Network Load Balancer, and use Amazon DynamoDB for the database."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a highly available and scalable architecture with minimal operational overhead. Deploying EC2 instances in an Auto Scaling group across multiple Availability Zones ensures automatic scaling and fault tolerance. An Application Load Balancer distributes traffic efficiently, and Amazon RDS Multi-AZ provides automatic failover for the relational database. Option B (incorrect) uses a single Availability Zone for both EC2 and RDS, creating a single point of failure and requiring manual scaling, which violates the high availability and automatic scaling requirements. Option C (incorrect) also uses a single Availability Zone for EC2 and a single Amazon Aurora instance, which does not provide the desired fault tolerance and high availability. Option D (incorrect) involves manual provisioning of EC2 instances, which increases operational overhead, and a Network Load Balancer is typically used for TCP/UDP traffic, not HTTP/HTTPS web applications, making it less suitable than an Application Load Balancer.', 19, 'm_19_2', 1, NULL, NULL),
  ('mock_18_all_1774925287644', 'A financial services company operates a critical analytics application that must have a Recovery Time Objective (RTO) of less than 5 minutes and a Recovery Point Objective (RPO) of less than 1 hour. The application runs on Amazon EC2 instances and stores data in Amazon RDS for PostgreSQL. They need a cost-effective disaster recovery strategy.', '["Implement a backup and restore strategy using AWS Backup for Amazon RDS and Amazon EBS snapshots, with manual recovery in a secondary Region.","Implement a warm standby strategy by maintaining a scaled-down version of the application in a secondary Region, using Amazon RDS Read Replicas and Amazon EC2 Auto Scaling.","Implement a pilot light strategy by keeping only the core database running in a secondary Region and manually launching EC2 instances upon disaster.","Implement a multi-site active/active strategy by deploying full application stacks in two Regions and using Amazon Route 53 for weighted routing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a warm standby strategy, which is cost-effective while meeting the RTO and RPO requirements. A scaled-down version in a secondary Region, along with Amazon RDS Read Replicas for data synchronization, allows for a quick scale-up and failover, achieving an RTO of less than 5 minutes and an RPO of less than 1 hour. Option A (incorrect) is a backup and restore strategy, which is generally the most cost-effective but typically has a much higher RTO (hours to days), failing to meet the <5 minute RTO. Option C (incorrect) is a pilot light strategy, which keeps only the core services running and typically has an RTO of 10+ minutes for full recovery, making it unsuitable for a <5 minute RTO. Option D (incorrect) is a multi-site active/active strategy, which provides the lowest RTO and RPO but is the most expensive, violating the ''cost-effective'' constraint.', 19, 'm_19_2', 2, NULL, NULL),
  ('mock_18_all_1774925287644', 'An e-commerce platform uses an Amazon RDS for MySQL database for its product catalog. During peak sales events, the database experiences high read loads, leading to slow response times. The company needs to improve read scalability and maintain high availability without significant application changes.', '["Migrate the database to Amazon DynamoDB to handle high read traffic and use DynamoDB Streams for replication.","Enable Multi-AZ deployment for the existing Amazon RDS for MySQL database to allow read traffic to the standby instance.","Create Amazon RDS Read Replicas from the existing Amazon RDS for MySQL database and distribute read traffic to them.","Provision a larger Amazon EC2 instance for the database server to increase its vertical scaling capacity."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate solution for improving read scalability and maintaining high availability for an Amazon RDS for MySQL database. Amazon RDS Read Replicas are specifically designed to offload read traffic from the primary database instance, allowing for horizontal scaling of reads. Option A (incorrect) suggests migrating to Amazon DynamoDB, which is a NoSQL database and would require significant application changes, violating the ''without significant application changes'' requirement. Option B (incorrect) is a common misconception; while Amazon RDS Multi-AZ provides high availability through an automatic failover standby instance, the standby instance does not serve read traffic. Option D (incorrect) describes vertical scaling, which can provide a temporary improvement but has limits and does not offer the same level of read scalability or fault tolerance as read replicas.', 19, 'm_19_2', 3, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global news agency needs to host a public website that must be highly available and resilient to regional outages. The website content is primarily static and frequently updated. Users worldwide must experience low latency when accessing the content.', '["Deploy the website on Amazon EC2 instances in a single Region and use Amazon Route 53 with a simple routing policy.","Host the static content on Amazon S3 in a single Region and use Amazon Route 53 with a failover routing policy without health checks.","Deploy the static website content to Amazon S3 buckets in multiple Regions and use an Application Load Balancer to distribute traffic.","Host the static website content in an Amazon S3 bucket, distribute it globally using Amazon CloudFront, and use Amazon Route 53 with a failover routing policy and associated health checks for regional failover."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the best solution for a global, highly available, low-latency static website. Amazon CloudFront caches content at edge locations worldwide, significantly reducing latency for users. Hosting the content in an Amazon S3 bucket provides high durability. Amazon Route 53 with a failover routing policy, combined with health checks, ensures automatic redirection to a healthy Region in case of an outage, providing regional fault tolerance. Option A (incorrect) uses a single Region and simple routing, which does not provide global low latency or resilience to regional outages. Option B (incorrect) uses Amazon S3 in a single Region and Amazon Route 53 failover without health checks, which means Route 53 would not automatically detect and react to failures, violating the resilience requirement. Option C (incorrect) deploys content to multiple S3 buckets but uses an Application Load Balancer, which is a regional service and cannot distribute traffic globally across Regions for static content hosted directly in S3.', 19, 'm_19_2', 4, NULL, NULL),
  ('mock_18_all_1774925287644', 'A pharmaceutical company needs to store petabytes of research data that is rarely accessed after its initial upload, but must be retained for regulatory compliance for several years. The primary requirement is to minimize storage costs while ensuring high durability.', '["Store the data in Amazon S3 Glacier Deep Archive.","Store the data in Amazon S3 Standard.","Store the data on Amazon EBS Provisioned IOPS SSD volumes.","Store the data on Amazon EFS Standard."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for storing petabytes of rarely accessed archival data with high durability. Amazon S3 Glacier Deep Archive is designed for long-term archiving at the lowest cost, with retrieval times ranging from 12 to 48 hours. Option B (incorrect) Amazon S3 Standard is designed for frequently accessed data and would be significantly more expensive for archival storage. Option C (incorrect) Amazon EBS Provisioned IOPS SSD volumes are block storage designed for high-performance, frequently accessed workloads attached to EC2 instances, making them unsuitable and very expensive for petabyte-scale archival storage. Option D (incorrect) Amazon EFS Standard is a scalable file system designed for shared access across EC2 instances and would also be much more expensive than S3 Glacier Deep Archive for long-term, rarely accessed archives.', 19, 'm_19_2', 5, NULL, NULL),
  ('mock_18_all_1774925287644', 'A media rendering farm uses a fleet of Amazon EC2 instances that require a shared file system to access common project files. These instances are deployed across multiple Availability Zones for high availability. The solution must be highly available and allow concurrent access from all instances.', '["Attach an Amazon EBS General Purpose SSD volume to each EC2 instance and manually synchronize data.","Use Amazon EFS Standard to provide a shared, highly available file system accessible from all EC2 instances across multiple Availability Zones.","Store project files in an Amazon S3 bucket and use the S3 API for file access from each EC2 instance.","Configure a single Amazon EC2 instance with a large local disk and share it via NFS to other instances."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the ideal solution for this scenario. Amazon EFS Standard provides a scalable, highly available, and durable file system that can be mounted and concurrently accessed by multiple Amazon EC2 instances across different Availability Zones. Option A (incorrect) Amazon EBS volumes are block storage attached to a single EC2 instance in a single AZ and cannot be shared across multiple instances or AZs without complex manual synchronization. Option C (incorrect) while Amazon S3 can store files, it is an object storage service and does not provide a traditional file system interface for direct mounting, requiring application changes to use its API. Option D (incorrect) configuring a single EC2 instance as an NFS server creates a single point of failure and introduces significant operational overhead for management and scaling, violating the high availability requirement.', 19, 'm_19_2', 6, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global manufacturing company needs to implement a disaster recovery strategy for its critical order processing application. The application runs on Amazon EC2 instances with an Amazon RDS for MySQL database. The RTO must be under 10 minutes, and the RPO must be under 1 hour. The company wants to minimize costs during normal operations.', '["Deploy a full, active-active application stack in two separate AWS Regions, using Amazon Route 53 for latency-based routing.","Implement a backup and restore strategy, using AWS Backup for Amazon RDS and Amazon EBS snapshots, with manual recovery in a secondary Region.","Maintain a scaled-down, non-production version of the application in a secondary Region, utilizing Amazon RDS Read Replicas for data synchronization.","Deploy the application in a single AWS Region and rely on Amazon RDS Multi-AZ and EC2 Auto Scaling for high availability within that Region."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a warm standby disaster recovery strategy. This approach involves maintaining a minimal, scaled-down version of the application in a secondary Region, with Amazon RDS Read Replicas ensuring data synchronization. This strategy offers a good balance between cost-effectiveness during normal operations and the ability to meet an RTO under 10 minutes and an RPO under 1 hour by quickly scaling up resources during a disaster. Option A (incorrect) is a multi-site active/active strategy, which provides the lowest RTO/RPO but is the most expensive, violating the ''minimize costs'' constraint during normal operations. Option B (incorrect) is a backup and restore strategy, which is the most cost-effective but typically has an RTO of several hours or more, failing to meet the <10 minute RTO. Option D (incorrect) only provides high availability within a single Region and does not protect against regional outages, failing the disaster recovery requirement.', 19, 'm_19_2', 7, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company hosts a critical API endpoint in `us-east-1` and needs to ensure continuous availability even if the entire `us-east-1` Region becomes unavailable. They have a replica of the API deployed in `us-west-2`. The solution must automatically redirect traffic to `us-west-2` upon detecting a failure in `us-east-1`.', '["Configure Amazon Route 53 with a simple routing policy pointing to the `us-east-1` API endpoint.","Use Amazon CloudFront to cache API responses and configure it to point to the `us-east-1` endpoint.","Implement a custom script to monitor the `us-east-1` API and manually update Amazon Route 53 DNS records during an outage.","Configure Amazon Route 53 with a failover routing policy, defining the `us-east-1` endpoint as primary and `us-west-2` as secondary, and associate Amazon Route 53 health checks with both endpoints."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the most robust and automated solution for regional failover. Configuring Amazon Route 53 with a failover routing policy allows you to designate primary and secondary endpoints. Crucially, associating Amazon Route 53 health checks with both endpoints enables Route 53 to automatically detect when the primary endpoint is unhealthy and redirect traffic to the secondary endpoint without manual intervention. Option A (incorrect) uses a simple routing policy, which does not provide any failover capabilities. Option B (incorrect) Amazon CloudFront can improve performance and availability for cached content but does not inherently provide regional failover for the origin API itself without Route 53. Option C (incorrect) relies on a manual script and manual updates, which increases the RTO and operational overhead, failing the ''automatically redirect'' requirement.', 19, 'm_19_2', 8, NULL, NULL),
  ('mock_18_all_1774925287644', 'A large enterprise needs to centralize and automate the backup of its Amazon RDS databases, Amazon EBS volumes, and Amazon EFS file systems. They require consistent backup policies, retention management, and compliance reporting across these services.', '["Use AWS Backup to create backup plans, assign resources, and manage retention policies for Amazon RDS, Amazon EBS, and Amazon EFS.","Manually create Amazon RDS snapshots, Amazon EBS snapshots, and use a custom script to copy Amazon EFS data to Amazon S3.","Configure each Amazon RDS database with Multi-AZ deployment and rely on Amazon EBS snapshots for EC2 instances, ignoring EFS.","Utilize Amazon S3 for all backup storage and develop custom AWS Lambda functions to trigger backups for each service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for centralized and automated backup management across multiple AWS services. AWS Backup is a fully managed service that allows you to define backup policies, schedule backups, and manage retention for Amazon RDS, Amazon EBS, Amazon EFS, and other services from a single console, ensuring compliance and reducing operational overhead. Option B (incorrect) involves manual creation of snapshots and custom scripting, which is prone to errors, lacks centralized management, and increases operational burden. Option C (incorrect) Amazon RDS Multi-AZ provides high availability, not a backup solution for data retention, and relying solely on EBS snapshots for EC2 instances while ignoring EFS does not meet the comprehensive backup requirement. Option D (incorrect) while Amazon S3 is excellent for storage, developing custom AWS Lambda functions for each service''s backup process is complex, time-consuming, and duplicates the functionality already provided by AWS Backup.', 19, 'm_19_2', 9, NULL, NULL);

