INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A web application processes user-uploaded images. The image processing is a long-running task that can take several minutes. The company wants to decouple the image upload from the processing logic to improve responsiveness and fault tolerance. Users should receive a notification once their image is processed.', '["Use Amazon SQS to queue image processing requests and an Amazon EC2 instance to poll the queue and process images. Send notifications via Amazon SNS.","Use Amazon SNS to publish image upload events, and an AWS Lambda function to process images directly. Send notifications via Amazon SQS.","Use Amazon EventBridge to trigger an AWS Lambda function for image processing. Send notifications via Amazon SQS.","Use Amazon API Gateway to receive image uploads, directly invoke an AWS Lambda function for processing, and return the result synchronously."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a robust, loosely coupled, and fault-tolerant architecture for this scenario. Amazon SQS acts as a buffer, decoupling the upload from the processing, improving responsiveness. EC2 instances can process images from the queue, allowing for long-running tasks. Amazon SNS is suitable for sending notifications to users. Option B (incorrect) using Amazon SNS to publish events is good for fan-out, but directly invoking an AWS Lambda function for image processing might exceed Lambda''s execution duration limits for long-running tasks. Also, using Amazon SQS for notifications is less direct than SNS for user notifications. Option C (incorrect) Amazon EventBridge is excellent for event routing, but an AWS Lambda function might not be suitable for long-running image processing tasks (up to 15 minutes). Option D (incorrect) directly invoking an AWS Lambda function and returning the result synchronously would block the user''s request for several minutes, violating the ''improve responsiveness'' requirement and potentially exceeding API Gateway''s integration timeouts.', 19, 'm_19_1', 10, NULL, NULL),
  ('mock_18_all_1774925287644', 'A microservices application needs to communicate asynchronously between its components to ensure loose coupling and resilience. When a new order is placed, several downstream services (e.g., inventory, shipping, billing) must be notified without the order service directly knowing about them. The solution should support fan-out messaging.', '["Implement direct HTTP API calls from the order service to each downstream service.","Use Amazon SQS queues for each downstream service, and the order service sends a message to each queue.","Use Amazon SNS to publish order events, and allow downstream services to subscribe to the SNS topic.","Use AWS Step Functions to orchestrate synchronous calls to each downstream service in parallel."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution for achieving loose coupling and fan-out messaging in a microservices architecture. Amazon SNS allows the order service to publish a single message to a topic, and multiple downstream services can subscribe to that topic, receiving the message simultaneously. This decouples the publisher from the subscribers. Option A (incorrect) involves direct HTTP API calls, which creates tight coupling between services and can lead to cascading failures if a downstream service is unavailable, violating the loose coupling and resilience requirements. Option B (incorrect) using separate Amazon SQS queues for each downstream service would require the order service to know about and send messages to each individual queue, increasing coupling and management overhead compared to SNS for fan-out. Option D (incorrect) AWS Step Functions is for orchestrating workflows, but using it for synchronous calls would still introduce tight coupling and potential blocking, contrary to the asynchronous and loosely coupled requirement.', 19, 'm_19_1', 11, NULL, NULL),
  ('mock_18_all_1774925287644', 'A gaming company is developing a new multiplayer game that uses UDP for real-time communication between game clients and dedicated game servers hosted on Amazon EC2 instances. They need a scalable and highly available load balancing solution for this non-HTTP traffic.', '["Use an Application Load Balancer (ALB) to distribute UDP traffic to the EC2 game servers.","Use Amazon API Gateway to expose the game server endpoints and handle UDP traffic.","Use a Network Load Balancer (NLB) to distribute UDP traffic to the EC2 game servers.","Implement a custom load balancing solution on an Amazon EC2 instance using a reverse proxy."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate choice for load balancing UDP traffic. A Network Load Balancer (NLB) is designed to handle extremely high performance and low latency for TCP, UDP, and TLS traffic, making it ideal for real-time gaming applications using UDP. Option A (incorrect) an Application Load Balancer (ALB) only supports HTTP/HTTPS traffic and cannot be used for UDP protocols. Option B (incorrect) Amazon API Gateway is designed for RESTful APIs and WebSocket APIs, not for raw UDP traffic from game clients. Option D (incorrect) implementing a custom load balancing solution on an Amazon EC2 instance increases operational overhead, introduces a single point of failure unless carefully designed, and is less scalable and reliable than a managed service like NLB.', 19, 'm_19_1', 12, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global media company hosts a popular news portal with a large amount of static and dynamic content. Users worldwide experience high latency when accessing the site during peak hours. The company wants to reduce latency for global users and offload traffic from their origin servers.', '["Implement Amazon CloudFront to cache both static and dynamic content at edge locations globally.","Use Amazon ElastiCache to cache database queries on the backend servers.","Increase the instance size of the Amazon EC2 web servers to handle more traffic.","Configure Amazon Route 53 with a simple routing policy to direct all traffic to a single Region."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for reducing latency for global users and offloading traffic from origin servers. Amazon CloudFront is a content delivery network (CDN) that caches both static and dynamic content at edge locations worldwide, serving content closer to users and reducing the load on backend servers. Option B (incorrect) Amazon ElastiCache is an in-memory caching service used to improve database performance by caching query results, but it does not address global latency for end-users accessing web content. Option C (incorrect) increasing EC2 instance size is vertical scaling, which can help with server load but does not reduce network latency for geographically dispersed users. Option D (incorrect) configuring Amazon Route 53 with a simple routing policy to a single Region would not reduce global latency and could even increase it for distant users.', 19, 'm_19_1', 13, NULL, NULL),
  ('mock_18_all_1774925287644', 'A data processing application uses an Amazon SQS queue to receive tasks. Worker Amazon EC2 instances continuously poll the queue for new messages. The current implementation uses short polling, resulting in a high number of empty responses and increased costs when the queue is often empty. The company wants to optimize cost and reduce empty responses.', '["Increase the number of Amazon EC2 worker instances to process messages faster.","Configure the Amazon SQS queue and the worker instances to use long polling by setting `WaitTimeSeconds` to a value greater than 0.","Switch from Amazon SQS to Amazon SNS for message queuing to reduce polling overhead.","Implement a custom backoff algorithm in the worker instances to reduce polling frequency after empty responses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective way to reduce empty responses and optimize cost for Amazon SQS polling. Long polling, achieved by setting `WaitTimeSeconds` to a value greater than 0, allows the SQS queue to wait for messages to arrive before returning a response, significantly reducing the number of empty responses and the associated API call costs. Option A (incorrect) increasing the number of worker instances would exacerbate the problem of empty responses and increase costs if the queue is frequently empty. Option C (incorrect) Amazon SNS is a publish/subscribe service, not a queueing service for worker tasks, and would not solve the polling issue. Option D (incorrect) implementing a custom backoff algorithm can help, but it''s a client-side solution that is more complex to manage and less efficient than leveraging SQS''s built-in long polling feature.', 19, 'm_19_1', 14, NULL, NULL),
  ('mock_18_all_1774925287644', 'A development team is building a new microservices application using containers. They want to deploy and manage their containers on AWS with the LEAST operational overhead, avoiding the need to provision, manage, or scale underlying server infrastructure.', '["Deploy containers on Amazon EC2 instances within an Auto Scaling group and manage them with Amazon ECS.","Deploy containers on Amazon EC2 instances and manage them with Amazon EKS.","Deploy containers using AWS Fargate with Amazon ECS.","Manually provision Amazon EC2 instances and deploy containers directly using Docker."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the LEAST operational overhead for container management. AWS Fargate is a serverless compute engine for Amazon ECS and Amazon EKS that allows you to run containers without having to provision, manage, or scale EC2 instances. You only pay for the resources consumed by your containers. Option A (incorrect) deploying on Amazon EC2 instances with Amazon ECS still requires managing the EC2 instances, including patching, updating, and scaling the underlying infrastructure. Option B (incorrect) Amazon EKS is a managed Kubernetes service, but when running on EC2 instances, it still requires managing the EC2 worker nodes, which increases operational overhead compared to Fargate. Option D (incorrect) manually provisioning EC2 instances and deploying containers directly is the most operationally intensive approach, requiring significant effort for scaling, patching, and high availability.', 19, 'm_19_1', 15, NULL, NULL),
  ('mock_18_all_1774925287644', 'A serverless application processes customer orders through a multi-step workflow. This workflow involves invoking several AWS Lambda functions sequentially, with some steps requiring conditional logic and parallel execution. The company needs a service to define, coordinate, and monitor these complex workflows.', '["Use Amazon SQS to queue messages between AWS Lambda functions for sequential processing.","Use Amazon SNS to fan out events to multiple AWS Lambda functions for parallel processing.","Implement a custom orchestration logic within an AWS Lambda function to invoke other Lambda functions.","Use AWS Step Functions to define and orchestrate the multi-step workflow, including sequential, parallel, and conditional logic."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the ideal service for defining, coordinating, and monitoring complex multi-step workflows in a serverless application. AWS Step Functions allows you to create state machines that orchestrate AWS Lambda functions and other AWS services, providing built-in capabilities for sequential, parallel, and conditional logic, error handling, and retries. Option A (incorrect) Amazon SQS is a message queueing service, suitable for decoupling and asynchronous communication, but it does not provide the orchestration capabilities, state management, or visual workflow definition needed for complex multi-step processes. Option B (incorrect) Amazon SNS is a publish/subscribe service primarily used for fan-out messaging, not for orchestrating sequential or conditional workflows. Option C (incorrect) implementing custom orchestration logic within an AWS Lambda function would be complex, difficult to maintain, and lack the built-in state management, error handling, and visual debugging provided by AWS Step Functions.', 19, 'm_19_1', 16, NULL, NULL),
  ('mock_18_all_1774925287644', 'A startup is launching a new mobile application that will interact with a backend API. They anticipate unpredictable traffic patterns, including sudden spikes. The API needs to be highly available, scalable, and protect the backend services from overload, while also providing authentication and authorization.', '["Deploy the API directly on Amazon EC2 instances behind an Application Load Balancer.","Use Amazon API Gateway to create the API endpoint, integrate it with AWS Lambda functions, and configure throttling and API keys.","Implement a custom API gateway on an Amazon EC2 instance to manage requests and security.","Expose the backend services directly to the internet and rely on application-level security."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable solution. Amazon API Gateway is a fully managed service that acts as a ''front door'' for applications to access data, business logic, or functionality from backend services. It inherently provides features like automatic scaling to handle traffic spikes, throttling to protect backend services, caching, and built-in authentication/authorization mechanisms, while integrating seamlessly with AWS Lambda. Option A (incorrect) deploying the API directly on Amazon EC2 instances behind an Application Load Balancer provides scalability and availability but requires more effort to implement API-specific features like throttling, API keys, and comprehensive authentication compared to API Gateway. Option C (incorrect) implementing a custom API gateway on an Amazon EC2 instance would significantly increase operational overhead, complexity, and maintenance, negating the benefits of managed services. Option D (incorrect) exposing backend services directly to the internet is a major security risk and lacks the essential features for managing and protecting an API, such as throttling and authentication.', 19, 'm_19_1', 17, NULL, NULL),
  ('mock_18_all_1774925287644', 'A social media platform needs to store user session data for its highly scalable web application. The session data must be accessible with very low latency (sub-millisecond) and be highly available to ensure users do not lose their sessions even if an application server fails. The solution should also reduce the load on the primary database.', '["Store session data in Amazon S3 buckets and retrieve it via API calls.","Use Amazon ElastiCache for Redis to store session data in-memory for low-latency access and high availability.","Store session data directly on Amazon EBS volumes attached to each application server.","Persist session data in an Amazon DynamoDB table with on-demand capacity."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the best choice for storing user session data with very low latency and high availability. Amazon ElastiCache for Redis is an in-memory data store that provides sub-millisecond response times and can be deployed in a highly available configuration across multiple Availability Zones. It effectively offloads session management from the primary database. Option A (incorrect) Amazon S3 is object storage, not designed for low-latency, transactional session data, and retrieving data via API calls would introduce higher latency than an in-memory cache. Option C (incorrect) Amazon EBS volumes are block storage attached to a single EC2 instance and are not suitable for shared, highly available session management across multiple application servers. This approach would also lead to session loss if the instance fails. Option D (incorrect) Amazon DynamoDB is a fast NoSQL database, but ElastiCache typically offers even lower latency for in-memory caching and is specifically designed for use cases like session stores to reduce primary database load.', 19, 'm_19_1', 18, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company is migrating its monolithic application to a microservices architecture. They need to ensure that the new microservices are loosely coupled and can communicate reliably without direct dependencies. One specific requirement is for a ''User Registration'' service to notify multiple other services (e.g., ''Welcome Email'', ''Profile Creation'', ''Analytics'') upon successful registration.', '["The User Registration service makes direct HTTP POST requests to each downstream service''s API endpoint.","The User Registration service writes registration events to an Amazon SQS queue, and each downstream service polls this queue independently.","The User Registration service publishes a ''UserRegistered'' event to an Amazon EventBridge event bus, with rules routing the event to specific targets for each downstream service.","The User Registration service uses AWS Step Functions to orchestrate a series of synchronous invocations to each downstream service."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most robust and loosely coupled solution for this event-driven microservices scenario. Amazon EventBridge provides a serverless event bus that allows the User Registration service to publish events without knowing the consumers. Rules can then filter and route these events to multiple specific targets (e.g., AWS Lambda, Amazon SQS, Amazon SNS) for each downstream service, ensuring complete decoupling. Option A (incorrect) making direct HTTP POST requests creates tight coupling, making the User Registration service dependent on the availability and responsiveness of all downstream services, which can lead to cascading failures. Option B (incorrect) while using an Amazon SQS queue provides decoupling, each downstream service would need to poll the same queue, or the User Registration service would need to send messages to multiple queues, which is less efficient for fan-out than EventBridge or SNS. Option D (incorrect) AWS Step Functions is for orchestrating workflows, but using it for synchronous invocations would still introduce tight coupling and potential blocking, contrary to the loosely coupled requirement.', 19, 'm_19_1', 19, NULL, NULL),
  ('mock_18_all_1774925287644', 'A data processing pipeline uses Amazon EC2 instances to process incoming data from an Amazon SQS queue. The workload is highly variable, and the company wants to automatically scale the number of EC2 instances based on the number of messages in the queue to optimize costs and ensure timely processing.', '["Manually adjust the number of Amazon EC2 instances based on periodic monitoring of the Amazon SQS queue depth.","Configure Amazon EC2 Auto Scaling to scale based on CPU utilization metrics of the EC2 instances.","Use AWS Lambda functions to process messages directly from the Amazon SQS queue, eliminating EC2 instances.","Configure Amazon EC2 Auto Scaling with a target tracking scaling policy based on the `ApproximateNumberOfMessagesVisible` metric of the Amazon SQS queue."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective and automated way to scale Amazon EC2 instances based on the Amazon SQS queue backlog. Amazon EC2 Auto Scaling can use custom metrics, including `ApproximateNumberOfMessagesVisible` from Amazon SQS, to dynamically adjust the desired capacity of the Auto Scaling group. A target tracking scaling policy will automatically add or remove instances to keep the queue depth at a desired level. Option A (incorrect) manual adjustment is not automated and does not meet the requirement for automatic scaling. Option B (incorrect) scaling based on CPU utilization might not accurately reflect the processing backlog if instances are idle but messages are accumulating in the queue. Option C (incorrect) while AWS Lambda can process messages from SQS, the question specifically asks about scaling Amazon EC2 instances for a data processing pipeline, implying a need for EC2 compute, and Lambda might not be suitable for very long-running or resource-intensive tasks that EC2 instances handle.', 19, 'm_19_1', 20, NULL, NULL);

