INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A company runs a legacy batch processing application on Amazon EC2 instances that currently process data for 8 hours daily. The application is fault-tolerant and can tolerate interruptions. The operations team wants to reduce compute costs significantly while maintaining the current processing capacity. Which solution is the MOST cost-effective for this scenario?', '["Migrate the application to use Amazon EC2 Spot Instances within an EC2 Auto Scaling group.","Purchase Amazon EC2 Reserved Instances for the entire 8-hour daily processing window.","Use Amazon EC2 On-Demand Instances and implement a custom script to shut them down after processing.","Re-architect the application to run on AWS Lambda functions for serverless execution."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution. Fault-tolerant batch workloads are ideal candidates for Amazon EC2 Spot Instances, which offer up to 90% savings compared to On-Demand pricing. Using an EC2 Auto Scaling group ensures capacity is maintained even if Spot Instances are interrupted. Option B (incorrect) involves purchasing Reserved Instances, which offer savings but are less flexible and typically more expensive than Spot Instances for interruptible workloads. Reserved Instances are better suited for stable, long-running workloads. Option C (incorrect) uses On-Demand Instances, which are the most expensive option for this type of workload, even with custom shutdown scripts. This approach does not leverage the significant cost savings available. Option D (incorrect) suggests re-architecting to AWS Lambda. While serverless, Lambda has a 15-minute execution limit, which might not be suitable for jobs that run for 8 hours daily or even complex transformations that could exceed this limit, requiring significant re-architecture and potentially Step Functions, adding complexity.', 20, 'm_20_2', 1, NULL, NULL),
  ('mock_18_all_1774925287644', 'A development team is building a new microservices application using Docker containers. They need to deploy these containers with minimal operational overhead for managing the underlying infrastructure, focusing solely on application code. The application has variable traffic patterns. Which compute solution meets these requirements with the LEAST operational overhead?', '["Deploy the containers on Amazon ECS with AWS Fargate launch type.","Deploy the containers on Amazon ECS with Amazon EC2 launch type using an Auto Scaling group.","Provision Amazon EC2 instances, install Docker, and manually deploy containers.","Use AWS Lambda to run the container images, triggered by API Gateway."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for minimal operational overhead. Amazon ECS with AWS Fargate launch type provides a serverless compute engine for containers, eliminating the need to provision, scale, or manage the underlying Amazon EC2 instances. The team can focus entirely on their application code and container images. Option B (incorrect) uses Amazon ECS with Amazon EC2 launch type, which requires managing the underlying EC2 instances, including patching, scaling, and capacity planning, increasing operational overhead. Option C (incorrect) involves manually provisioning EC2 instances and managing Docker, which is a highly operational and inefficient approach, completely contradicting the ''minimal operational overhead'' requirement. Option D (incorrect) suggests using AWS Lambda for container images. While Lambda is serverless, it has a 15-minute execution limit, which might not be suitable for all microservices, and managing container images within Lambda has specific considerations that might not align with a general Docker container deployment strategy for microservices.', 20, 'm_20_2', 2, NULL, NULL),
  ('mock_18_all_1774925287644', 'A data analytics team needs to process large datasets (several terabytes) daily. The processing jobs can run for up to 30 minutes and involve complex transformations. They require a fully managed, scalable solution that can handle these long-running tasks efficiently. Which AWS service combination provides the MOST scalable and fully managed solution?', '["Use AWS Lambda functions orchestrated by AWS Step Functions to process the data.","Implement the processing jobs using AWS Batch, triggered by Amazon S3 events.","Run the data processing jobs on a self-managed Apache Spark cluster on Amazon EC2 instances.","Utilize Amazon EMR clusters that are manually provisioned and managed for each job."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most scalable and fully managed solution for long-running batch jobs. AWS Batch allows users to run batch computing workloads on AWS, dynamically provisioning and scaling compute resources (EC2 instances, Spot Instances, or Fargate) based on job requirements. It''s ideal for jobs that can run for up to 30 minutes or longer. Option A (incorrect) suggests AWS Lambda. While serverless, AWS Lambda has a maximum execution timeout of 15 minutes, making it unsuitable for jobs that run for 30 minutes. Orchestrating with Step Functions would still require breaking down the job into smaller, sub-15-minute Lambda functions, adding complexity. Option C (incorrect) involves a self-managed Apache Spark cluster on Amazon EC2, which requires significant operational overhead for provisioning, scaling, patching, and monitoring the EC2 instances, failing the ''fully managed'' requirement. Option D (incorrect) uses Amazon EMR, which is suitable for big data processing, but the option specifies ''manually provisioned and managed,'' which increases operational overhead compared to the serverless nature of AWS Batch or a more automated EMR setup.', 20, 'm_20_2', 3, NULL, NULL),
  ('mock_18_all_1774925287644', 'An e-commerce website experiences predictable daily traffic spikes, requiring more compute capacity during peak hours. The current setup uses a fixed number of Amazon EC2 instances, leading to over-provisioning during off-peak times. The company wants to optimize costs and performance. Which solution is the MOST cost-effective and elastic?', '["Configure an Amazon EC2 Auto Scaling group with scaling policies based on CPU utilization.","Manually scale Amazon EC2 instances up before peak hours and down after peak hours.","Purchase Amazon EC2 Reserved Instances for the maximum required capacity.","Migrate the entire application to AWS Lambda to handle all traffic."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and elastic solution. An Amazon EC2 Auto Scaling group dynamically adjusts the number of EC2 instances based on demand, such as CPU utilization. This prevents over-provisioning during low traffic and ensures sufficient capacity during peak times, optimizing both cost and performance. Option B (incorrect) involves manual scaling, which is prone to human error, can lead to either over-provisioning or under-provisioning, and is not elastic. Option C (incorrect) suggests purchasing Reserved Instances for maximum capacity. While Reserved Instances offer cost savings, buying them for peak capacity means paying for unused capacity during off-peak hours, making it less cost-effective and not elastic. Option D (incorrect) proposes migrating the entire application to AWS Lambda. While Lambda is highly elastic and serverless, a full migration might be a significant re-architecture effort, and not all e-commerce applications are suitable for a pure Lambda architecture without careful design, especially if they have long-running processes or specific state requirements.', 20, 'm_20_2', 4, NULL, NULL),
  ('mock_18_all_1774925287644', 'A development team is building a new microservices application using Docker containers. They need to deploy these containers with minimal operational overhead for managing the underlying infrastructure, focusing solely on application code. The application has variable traffic patterns. Which compute solution meets these requirements with the LEAST operational overhead?', '["Deploy the containers on Amazon ECS with AWS Fargate launch type.","Deploy the containers on Amazon ECS with Amazon EC2 launch type using an Auto Scaling group.","Provision Amazon EC2 instances, install Docker, and manually deploy containers.","Use AWS Lambda to run the container images, triggered by Amazon API Gateway."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for minimal operational overhead. Amazon ECS with AWS Fargate launch type provides a serverless compute engine for containers, eliminating the need to provision, scale, or manage the underlying Amazon EC2 instances. The team can focus entirely on their application code and container images. Option B (incorrect) uses Amazon ECS with Amazon EC2 launch type, which requires managing the underlying EC2 instances, including patching, scaling, and capacity planning, increasing operational overhead. Option C (incorrect) involves manually provisioning EC2 instances and managing Docker, which is a highly operational and inefficient approach, completely contradicting the ''minimal operational overhead'' requirement. Option D (incorrect) suggests using AWS Lambda for container images. While Lambda is serverless, it has a 15-minute execution limit, which might not be suitable for all microservices, and managing container images within Lambda has specific considerations that might not align with a general Docker container deployment strategy for microservices.', 20, 'm_20_2', 5, NULL, NULL);

