INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A global media company hosts its website on Amazon S3 for static content and serves dynamic content from Amazon EC2 instances. Users worldwide report varying latency, especially for dynamic content. The company wants to improve content delivery performance and reduce latency for all users. Which combination of services achieves the LOWEST global latency for both static and dynamic content?', '["Distribute both static and dynamic content through Amazon CloudFront, with EC2 instances as an origin.","Use Amazon Global Accelerator to route traffic to the EC2 instances and serve static content directly from S3.","Configure an Application Load Balancer (ALB) in each region and use Route 53 latency-based routing.","Replicate the EC2 instances to multiple AWS Regions and use Route 53 geolocation routing for dynamic content."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the lowest global latency for both static and dynamic content. Amazon CloudFront is a global Content Delivery Network (CDN) that caches static content at edge locations close to users and optimizes dynamic content delivery through persistent connections and network optimizations to the origin. This reduces latency for all types of content. Option B (incorrect) uses Amazon Global Accelerator, which improves performance for TCP/UDP traffic by routing it over the AWS global network, but it doesn''t cache static content at the edge like CloudFront, nor does it optimize dynamic content delivery in the same way as CloudFront''s persistent connections. Serving static content directly from S3 without a CDN would still result in higher latency for distant users. Option C (incorrect) uses ALBs and Route 53 latency-based routing. While this helps direct users to the closest regional endpoint, it doesn''t provide edge caching for static content or the same level of network optimization for dynamic content as CloudFront. Option D (incorrect) involves replicating EC2 instances across regions and using Route 53 geolocation routing. This improves regional availability but still lacks the edge caching and dynamic content optimization benefits of a CDN like CloudFront.', 20, 'm_20_4', 6, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company needs to establish a secure, private, and consistently low-latency connection between its on-premises data center and its AWS VPC. The data transfer volume is consistently high, and network performance is critical for their real-time applications. Which AWS service provides the MOST consistent low-latency and high-throughput connectivity?', '["Establish an AWS Direct Connect connection between the data center and the AWS Region.","Configure an AWS Site-to-Site VPN connection over the public internet.","Use a software VPN solution running on an Amazon EC2 instance in the VPC.","Transfer data periodically using AWS DataSync over the public internet."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for consistent low-latency and high-throughput connectivity. AWS Direct Connect provides a dedicated private network connection from an on-premises data center to AWS, bypassing the public internet. This ensures consistent network performance, which is critical for real-time applications and high data transfer volumes. Option B (incorrect) uses an AWS Site-to-Site VPN connection. While secure, VPN connections traverse the public internet, meaning latency and throughput can be variable and are not guaranteed, making it unsuitable for ''consistently low-latency'' requirements. Option C (incorrect) involves a software VPN on an EC2 instance, which introduces additional management overhead and still relies on the public internet for connectivity, similar to a Site-to-Site VPN. Option D (incorrect) suggests AWS DataSync over the public internet. DataSync is for large-scale data transfer, but it''s not designed for real-time, consistently low-latency application connectivity and still relies on the public internet, which can have variable performance.', 20, 'm_20_4', 7, NULL, NULL),
  ('mock_18_all_1774925287644', 'A large enterprise has over 15 VPCs across multiple AWS accounts in a single region. They need to establish secure and scalable network connectivity between all these VPCs, allowing resources in any VPC to communicate with resources in any other VPC. Which AWS service provides the MOST scalable and manageable network architecture?', '["Implement AWS Transit Gateway to centralize routing between all VPCs.","Create a full mesh of VPC peering connections between all 15+ VPCs.","Set up a dedicated Amazon EC2 instance in a central VPC to act as a router.","Use AWS VPN connections to connect each VPC to a central on-premises router."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most scalable and manageable solution for connecting a large number of VPCs. AWS Transit Gateway acts as a central hub for connecting VPCs and on-premises networks, simplifying network architecture and enabling transitive routing between connected VPCs. This avoids the complexity of managing numerous individual connections. Option B (incorrect) suggests a full mesh of VPC peering connections. VPC peering connections are non-transitive, meaning each VPC would need a direct connection to every other VPC. For 15+ VPCs, this would result in O(n^2) connections (over 100 connections for 15 VPCs), which is unmanageable and not scalable. Option C (incorrect) involves using an EC2 instance as a router. This is a single point of failure, requires manual management, and does not scale well for high throughput or a large number of connections. Option D (incorrect) proposes using AWS VPN connections to connect each VPC to a central on-premises router. This introduces an unnecessary dependency on the on-premises network for inter-VPC communication and would likely incur higher latency and cost compared to an in-AWS solution like Transit Gateway.', 20, 'm_20_4', 8, NULL, NULL),
  ('mock_18_all_1774925287644', 'A web application running on Amazon EC2 instances behind an Application Load Balancer (ALB) experiences high traffic. The backend instances need to communicate with an internal service hosted in another private subnet within the same VPC. The company wants to ensure secure and efficient internal communication. Which networking component should be used to control traffic between the application instances and the internal service?', '["Configure Security Groups to allow specific traffic between the application and internal service subnets.","Use Network Access Control Lists (NACLs) to filter traffic at the subnet level for all communication.","Establish a VPC peering connection between the two subnets for direct communication.","Implement an AWS Transit Gateway to route traffic between the application and internal service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the appropriate component for controlling traffic between instances within the same VPC. Security Groups act as a virtual firewall for instances, controlling inbound and outbound traffic at the instance level. They are stateful and allow fine-grained control over specific ports and protocols between the application EC2 instances and the internal service instances. Option B (incorrect) suggests Network Access Control Lists (NACLs). While NACLs filter traffic at the subnet level, they are stateless and apply to all traffic entering or leaving the subnet, making them less granular and more complex to manage for instance-to-instance communication within the same VPC compared to Security Groups. Option C (incorrect) proposes a VPC peering connection between two subnets. VPC peering connects entire VPCs, not just subnets within the same VPC. This is an incorrect use case as the services are already within the same VPC. Option D (incorrect) involves an AWS Transit Gateway. Transit Gateway is used for connecting multiple VPCs or on-premises networks, not for controlling traffic between subnets within a single VPC.', 20, 'm_20_4', 9, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global media company hosts its website on Amazon S3 for static content and serves dynamic content from Amazon EC2 instances. Users worldwide report varying latency, especially for dynamic content. The company wants to improve content delivery performance and reduce latency for all users. Which combination of services achieves the LOWEST global latency for both static and dynamic content?', '["Distribute both static and dynamic content through Amazon CloudFront, with EC2 instances as an origin.","Use AWS Global Accelerator to route traffic to the EC2 instances and serve static content directly from Amazon S3.","Configure an Application Load Balancer (ALB) in each region and use Amazon Route 53 latency-based routing.","Replicate the EC2 instances to multiple AWS Regions and use Amazon Route 53 geolocation routing for dynamic content."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the lowest global latency for both static and dynamic content. Amazon CloudFront is a global Content Delivery Network (CDN) that caches static content at edge locations close to users and optimizes dynamic content delivery through persistent connections and network optimizations to the origin. This reduces latency for all types of content. Option B (incorrect) uses AWS Global Accelerator, which improves performance for TCP/UDP traffic by routing it over the AWS global network, but it doesn''t cache static content at the edge like CloudFront, nor does it optimize dynamic content delivery in the same way as CloudFront''s persistent connections. Serving static content directly from Amazon S3 without a CDN would still result in higher latency for distant users. Option C (incorrect) uses ALBs and Amazon Route 53 latency-based routing. While this helps direct users to the closest regional endpoint, it doesn''t provide edge caching for static content or the same level of network optimization for dynamic content as CloudFront. Option D (incorrect) involves replicating EC2 instances across regions and using Amazon Route 53 geolocation routing. This improves regional availability but still lacks the edge caching and dynamic content optimization benefits of a CDN like CloudFront.', 20, 'm_20_4', 10, NULL, NULL);

