-- Module: m_20_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A financial analytics application runs on a single Amazon EC2 instance and requires extremely low-latency, high-performance block storage for its transactional database. The current Amazon EBS gp2 volume is experiencing performance bottlenecks during peak processing. Which EBS volume type provides the HIGHEST sustained performance with the lowest latency for this single instance?', '["Migrate to an Amazon EBS io2 Block Express volume.","Increase the size of the existing Amazon EBS gp2 volume to gain more IOPS.","Switch to an Amazon EBS gp3 volume with provisioned IOPS and throughput.","Attach an Amazon EFS file system to the EC2 instance for shared storage."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best choice for the highest sustained performance and lowest latency for a single instance. Amazon EBS io2 Block Express volumes are designed for the highest performance, offering tens of thousands of IOPS and thousands of MiB/s of throughput, with sub-millisecond latency, making them ideal for critical, high-performance transactional databases. Option B (incorrect) suggests increasing the size of the existing gp2 volume. While gp2 performance scales with size, it relies on burst credits for high performance and can still experience bottlenecks under sustained heavy load. It''s not designed for the absolute highest sustained performance. Option C (incorrect) proposes switching to an Amazon EBS gp3 volume. gp3 offers a consistent baseline performance (3,000 IOPS and 125 MiB/s included) and allows independent provisioning of IOPS and throughput, which is better than gp2 for many workloads. However, io2 Block Express offers significantly higher maximum performance and lower latency for the most demanding applications. Option D (incorrect) recommends attaching an Amazon EFS file system. EFS is a network file system designed for shared access and scalability, but it introduces network latency and is not optimized for the lowest latency, single-instance block storage required by a transactional database.', 20, 'm_20_1', 11, NULL, NULL),
  ('mock_18_all_1774925287644', 'A team of data scientists needs a shared file system for their Amazon EC2 instances to store and process large datasets. The file system must support POSIX compliance, allow multiple instances to read and write concurrently, and scale automatically. Which AWS storage service meets these requirements?', '["Use Amazon EFS for a scalable, shared, and POSIX-compliant file system.","Store the datasets in Amazon S3 buckets and access them via the S3 API.","Attach individual Amazon EBS gp3 volumes to each EC2 instance and synchronize data manually.","Provision an Amazon FSx for Windows File Server for shared access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. Amazon EFS provides a scalable, elastic, and fully managed network file system that supports POSIX file system semantics. It allows multiple Amazon EC2 instances to access the same file system concurrently, making it perfect for shared data processing workloads like those used by data scientists. Option B (incorrect) suggests storing data in Amazon S3. Amazon S3 is object storage and does not support POSIX file system semantics (e.g., no file locking, append operations, or traditional directory structure), making it unsuitable for applications requiring a true file system. Option C (incorrect) involves attaching individual Amazon EBS gp3 volumes. EBS volumes are block storage, designed for single-instance attachment. Sharing data between multiple instances would require complex and error-prone manual synchronization or clustering software, which is not scalable or efficient. Option D (incorrect) proposes Amazon FSx for Windows File Server. While FSx provides shared file systems, FSx for Windows File Server is specifically for Windows-based workloads and SMB protocol, whereas the scenario implies a more general-purpose, likely Linux-based, data science environment where EFS is typically preferred for its native POSIX support.', 20, 'm_20_1', 12, NULL, NULL),
  ('mock_18_all_1774925287644', 'A content management system stores millions of small, frequently accessed image and document files. These files are accessed via HTTP/HTTPS by a global audience. The company requires highly durable, highly available, and cost-effective object storage. Which AWS service is BEST suited for this use case?', '["Store the files in Amazon S3 with appropriate lifecycle policies.","Use Amazon EFS to store the files and serve them via an EC2 instance.","Attach Amazon EBS gp3 volumes to EC2 instances and host the files.","Archive the files in Amazon S3 Glacier Deep Archive for long-term retention."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best choice. Amazon S3 is highly durable, highly available, and cost-effective object storage, perfectly suited for storing static web content like images and documents. It can serve content directly via HTTP/HTTPS and integrates seamlessly with Amazon CloudFront for global content delivery. Lifecycle policies can further optimize costs by moving less frequently accessed objects to colder storage classes. Option B (incorrect) suggests Amazon EFS. EFS is a network file system, not object storage, and is typically used for shared file access by EC2 instances. While it can store files, serving them globally via HTTP/HTTPS would require additional infrastructure (e.g., EC2 instances, load balancers), increasing complexity and cost compared to S3. Option C (incorrect) involves Amazon EBS volumes. EBS is block storage attached to a single EC2 instance. It is not designed for highly available, globally accessible object storage and would require significant architectural effort to achieve the desired durability and availability for web content. Option D (incorrect) proposes Amazon S3 Glacier Deep Archive. This storage class is designed for long-term archival with retrieval times measured in hours, making it entirely unsuitable for ''frequently accessed'' files that need to be served to a global audience.', 20, 'm_20_1', 13, NULL, NULL),
  ('mock_18_all_1774925287644', 'A media production studio needs to migrate 50 TB of video archives from its on-premises data center to Amazon S3. The studio has limited internet bandwidth, and transferring the data over the network would take several weeks. Which AWS service provides the FASTEST and MOST cost-effective data transfer for this large dataset?', '["Use AWS Snowball to physically ship the data to AWS for ingestion into Amazon S3.","Utilize AWS DataSync to transfer the data over the internet with bandwidth throttling.","Set up an AWS Transfer Family SFTP endpoint and transfer data over the internet.","Provision a dedicated AWS Direct Connect link to increase network bandwidth."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the fastest and most cost-effective solution for transferring 50 TB of data with limited internet bandwidth. AWS Snowball provides physical devices that are shipped to the customer''s data center, loaded with data, and then shipped back to AWS for direct ingestion into Amazon S3. This bypasses network limitations and is significantly faster and often more cost-effective for large datasets than network transfers. Option B (incorrect) suggests AWS DataSync over the internet. While DataSync is efficient for network transfers, 50 TB over limited bandwidth would still take a very long time, and bandwidth throttling would further slow it down, failing the ''fastest'' requirement. Option C (incorrect) involves AWS Transfer Family SFTP. This service facilitates file transfers over the internet using SFTP, FTPS, or FTP. It still relies on the existing internet bandwidth and would face the same time constraints as DataSync for such a large volume. Option D (incorrect) proposes provisioning a dedicated AWS Direct Connect link. While Direct Connect provides high-bandwidth private connectivity, it involves significant setup time and ongoing costs, which might not be the most cost-effective or fastest initial transfer method for a one-time migration of 50 TB, especially when Snowball is available.', 20, 'm_20_1', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A popular social media application uses Amazon RDS for PostgreSQL as its primary database. The application experiences frequent read spikes, causing performance degradation for users. The development team needs to offload read traffic to improve response times without modifying the application logic significantly. Which solution provides the HIGHEST read scalability with minimal application changes?', '["Create Amazon RDS Read Replicas and configure the application to distribute read queries.","Migrate the entire database to Amazon DynamoDB for its high read/write throughput.","Implement an Amazon ElastiCache for Redis cluster to cache frequently accessed data.","Upgrade the Amazon RDS instance to a larger, more powerful instance type."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the highest read scalability with minimal application changes for an Amazon RDS database. Amazon RDS Read Replicas allow you to offload read traffic from the primary database instance to one or more replicas. The application can be configured to direct read queries to the replicas, significantly improving read performance and scalability without requiring a complete re-architecture of the database or application logic. Option B (incorrect) suggests migrating to Amazon DynamoDB. While DynamoDB offers high read/write throughput and scalability, it is a NoSQL database and would require a significant re-architecture of the application and data model to accommodate its key-value/document structure, which contradicts ''minimal application changes.'' Option C (incorrect) proposes an Amazon ElastiCache for Redis cluster. Caching is excellent for improving performance for frequently accessed, identical queries. However, it requires application logic changes to implement caching strategies and invalidation, and it doesn''t scale all read queries, only those that can be cached. Option D (incorrect) involves upgrading the RDS instance type. While this might provide a temporary performance boost, it''s a vertical scaling solution with inherent limits and does not offer the same level of horizontal read scalability as Read Replicas, especially for frequent spikes.', 20, 'm_20_3', 15, NULL, NULL),
  ('mock_18_all_1774925287644', 'An online gaming platform needs a database to store user profiles, game scores, and session data. This data has a simple key-value structure, high read/write throughput requirements, and needs to scale globally with extremely low latency. Complex joins are not required. Which AWS database service is BEST suited for this use case?', '["Use Amazon DynamoDB for its highly scalable, low-latency NoSQL capabilities.","Deploy Amazon Aurora with a multi-master configuration for high availability.","Provision an Amazon RDS for MySQL instance with multiple read replicas.","Implement Amazon Redshift for analytical querying of game data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best choice for this scenario. Amazon DynamoDB is a fully managed, serverless NoSQL database service that provides single-digit millisecond performance at any scale. Its key-value and document data model is ideal for user profiles, game scores, and session data, especially when complex joins are not required. It offers high read/write throughput and global tables for multi-region, low-latency access. Option B (incorrect) suggests Amazon Aurora with a multi-master configuration. Aurora is a relational database designed for high performance and availability, but it is optimized for relational workloads requiring complex joins and transactions. While powerful, it''s generally overkill and less cost-effective for simple key-value data with extreme scalability requirements compared to DynamoDB. Option C (incorrect) proposes Amazon RDS for MySQL with read replicas. RDS is a relational database and, like Aurora, is not optimized for simple key-value access patterns at massive scale with extremely low latency globally. Read replicas help with read scaling but don''t address the core requirement for a highly scalable key-value store. Option D (incorrect) recommends Amazon Redshift. Redshift is a data warehousing service optimized for analytical queries on large datasets, not for transactional, low-latency operational data like user profiles or game scores.', 20, 'm_20_3', 16, NULL, NULL),
  ('mock_18_all_1774925287644', 'A frequently accessed product catalog application queries an Amazon RDS for MySQL database. Many queries are identical and repeatedly fetch the same product details, leading to increased database load and slower response times. The team wants to reduce database load and improve read performance. Which solution BEST addresses this requirement?', '["Implement an Amazon ElastiCache for Memcached cluster to cache product details.","Add more Amazon RDS Read Replicas to distribute the read load.","Upgrade the Amazon RDS instance to a larger, more powerful instance type.","Migrate the product catalog to Amazon DynamoDB for better read performance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for improving performance for repeated, identical read queries. Amazon ElastiCache for Memcached (or Redis) is an in-memory caching service that stores frequently accessed data, reducing the load on the primary database and significantly improving response times for subsequent requests. This directly addresses the problem of ''many queries are identical and repeatedly fetch the same product details.'' Option B (incorrect) suggests adding more Amazon RDS Read Replicas. While Read Replicas help distribute the overall read load, they still query the database. For identical, repeated queries, caching is more efficient as it avoids hitting the database altogether. Option C (incorrect) proposes upgrading the Amazon RDS instance. This is a vertical scaling approach that might provide some temporary relief but does not fundamentally solve the problem of inefficient repeated queries hitting the database. It''s also less cost-effective than caching for this specific access pattern. Option D (incorrect) involves migrating to Amazon DynamoDB. This would be a significant re-architecture effort, and while DynamoDB offers high read performance, it''s a NoSQL database. Caching is a more targeted and less disruptive solution for improving performance of repeated reads from an existing relational database.', 20, 'm_20_3', 17, NULL, NULL),
  ('mock_18_all_1774925287644', 'A serverless application built with AWS Lambda functions frequently connects to an Amazon RDS for PostgreSQL database. During peak load, the database experiences connection exhaustion, leading to application errors. The development team needs a solution to manage database connections efficiently. Which AWS service BEST addresses this issue?', '["Implement Amazon RDS Proxy between the Lambda functions and the RDS database.","Increase the `max_connections` parameter in the Amazon RDS parameter group.","Use Amazon ElastiCache for Redis to reduce the number of direct database connections.","Migrate the database to Amazon Aurora Serverless v2 for automatic connection scaling."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for managing database connections from AWS Lambda functions. Amazon RDS Proxy pools and reuses database connections, preventing connection exhaustion that often occurs with serverless functions due to their ephemeral nature and concurrent invocations. It provides a highly available, fully managed connection pooling service. Option B (incorrect) suggests increasing the `max_connections` parameter. While this might temporarily alleviate the issue, it has limits and can put additional strain on the database''s memory and CPU, potentially leading to other performance problems. It''s not a scalable solution for the bursty connection patterns of Lambda. Option C (incorrect) proposes using Amazon ElastiCache for Redis. ElastiCache is a caching service that can reduce database load by serving cached data, but it does not directly solve the problem of connection exhaustion from Lambda functions that still need to interact with the database for non-cached operations. Option D (incorrect) involves migrating to Amazon Aurora Serverless v2. While Aurora Serverless v2 offers automatic scaling for compute and connections, it''s a significant database migration and re-architecture effort. RDS Proxy provides a targeted solution for connection management for existing RDS databases without requiring a full migration.', 20, 'm_20_3', 18, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_20_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A logistics company needs to collect real-time sensor data from thousands of delivery vehicles. The data arrives continuously, is time-ordered, and needs to be processed immediately for live tracking and anomaly detection. Which AWS service provides the MOST efficient real-time ingestion and processing of this time-ordered data?', '["Use Amazon Kinesis Data Streams to ingest and process the real-time, time-ordered data.","Send the sensor data to an Amazon SQS queue and process it with AWS Lambda functions.","Store the sensor data directly in Amazon S3 and process it with AWS Glue batch jobs.","Write the sensor data to an Amazon RDS for PostgreSQL database for immediate access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient solution for real-time ingestion and processing of time-ordered data. Amazon Kinesis Data Streams is specifically designed for collecting, processing, and analyzing streaming data in real time. It ensures data ordering within a shard and allows for immediate consumption by downstream applications for live tracking and anomaly detection. Option B (incorrect) suggests Amazon SQS. SQS is a message queuing service that is not optimized for time-ordered data streams or real-time processing of continuous data. While it can ingest data, it doesn''t guarantee ordering and is typically used for decoupling components rather than real-time stream processing. Option C (incorrect) involves storing data in Amazon S3 and processing with AWS Glue batch jobs. This is a batch processing approach, which is unsuitable for the requirement of ''immediately'' processing data for ''live tracking and anomaly detection.'' Option D (incorrect) proposes writing sensor data to an Amazon RDS for PostgreSQL database. While RDS can store data, it is not designed for the high-volume, continuous ingestion of real-time streaming data from thousands of sources and would quickly become a bottleneck, leading to performance issues and high costs.', 20, 'm_20_5', 19, NULL, NULL),
  ('mock_18_all_1774925287644', 'A data engineering team needs to perform extract, transform, and load (ETL) operations on large datasets stored in Amazon S3. The transformations involve complex data cleaning and schema conversions. They require a serverless, auto-scaling service to minimize operational overhead. Which AWS service is BEST suited for this task?', '["Utilize AWS Glue for serverless, auto-scaling ETL jobs.","Provision and manage an Amazon EMR cluster for batch processing.","Develop custom Python scripts on Amazon EC2 instances for ETL.","Use Amazon Athena to query and transform data directly in Amazon S3."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for serverless, auto-scaling ETL jobs with minimal operational overhead. AWS Glue is a fully managed, serverless ETL service that automatically provisions and scales the necessary resources for data transformation. It integrates with the AWS Glue Data Catalog and supports various data formats and complex transformations. Option B (incorrect) suggests provisioning and managing an Amazon EMR cluster. While EMR is powerful for big data processing, it requires provisioning, managing, and scaling the underlying EC2 instances, which increases operational overhead and contradicts the ''serverless, auto-scaling'' requirement. Option C (incorrect) involves developing custom Python scripts on Amazon EC2 instances. This approach requires significant manual effort for infrastructure provisioning, scaling, maintenance, and monitoring, making it highly operational and inefficient. Option D (incorrect) proposes using Amazon Athena. Athena is a serverless query service for data in S3, but it is primarily for ad-hoc querying and analysis, not for complex, programmatic ETL transformations that involve data cleaning and schema conversions, which are better handled by a dedicated ETL service like AWS Glue.', 20, 'm_20_5', 20, NULL, NULL),
  ('mock_18_all_1774925287644', 'A research institution generates petabytes of scientific data annually, stored in Amazon S3. Researchers need to query this data using standard SQL without provisioning or managing any compute infrastructure. The queries are ad-hoc and can be complex. Which AWS service provides the MOST cost-effective and serverless SQL querying of data in Amazon S3?', '["Use Amazon Athena to run SQL queries directly on data in Amazon S3.","Load the data into an Amazon Redshift cluster for SQL querying.","Provision an Amazon EMR cluster and use Apache Hive for SQL queries.","Develop custom applications on Amazon EC2 instances to process the data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective and serverless solution for SQL querying data in Amazon S3. Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon S3 using standard SQL. It is serverless, meaning there is no infrastructure to provision or manage, and you pay only for the data scanned by your queries, making it highly cost-effective for ad-hoc queries on large datasets. Option B (incorrect) suggests loading data into an Amazon Redshift cluster. Redshift is a data warehouse that requires provisioning and managing clusters, incurring continuous costs even when not actively querying. It''s not serverless and less cost-effective for ad-hoc queries on data already in S3. Option C (incorrect) proposes an Amazon EMR cluster with Apache Hive. EMR requires provisioning and managing EC2 instances, increasing operational overhead and cost compared to a serverless solution like Athena. Option D (incorrect) involves custom applications on Amazon EC2 instances. This approach requires significant development, provisioning, and management effort, making it neither serverless nor cost-effective for ad-hoc SQL querying.', 20, 'm_20_5', 21, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company wants to build a central data lake on Amazon S3 to store all its raw and processed data. They need a way to easily discover, catalog, and secure fine-grained access to different datasets within this lake for various analytics tools and users. Which AWS service BEST facilitates cataloging and securing access to data lake assets?', '["Implement AWS Lake Formation to centralize security, governance, and auditing for the data lake.","Rely solely on Amazon S3 bucket policies and IAM roles for access control.","Use AWS Glue Data Catalog for metadata storage and manage access with custom scripts.","Store data in Amazon Redshift and use its built-in security features for access control."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the best solution for centralizing security, governance, and auditing for a data lake. AWS Lake Formation simplifies building, securing, and managing data lakes by providing a central console to define security, governance, and auditing policies. It allows for fine-grained access control down to the column and row level for data stored in Amazon S3, making it easy to manage access for various analytics tools and users. Option B (incorrect) suggests relying solely on Amazon S3 bucket policies and IAM roles. While essential, managing fine-grained access control (e.g., column-level security) across many datasets and users using only S3 policies and IAM roles can become complex, difficult to scale, and prone to errors. Option C (incorrect) proposes using AWS Glue Data Catalog for metadata storage and custom scripts for access. The Glue Data Catalog is excellent for cataloging, but it doesn''t inherently provide the centralized security and fine-grained access control mechanisms that Lake Formation offers. Custom scripts would increase operational overhead and complexity. Option D (incorrect) involves storing data in Amazon Redshift. Redshift is a data warehouse, not a data lake. While it has security features, it requires moving data out of the S3 data lake, which defeats the purpose of a central data lake and adds unnecessary data duplication and cost.', 20, 'm_20_5', 22, NULL, NULL);

