INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A media company runs a batch processing workload on Amazon EC2 instances that can tolerate interruptions and has flexible start and end times. The workload processes large video files for transcoding, typically running for several hours daily. The company''s primary goal is to minimize compute costs for this specific workload. Which EC2 purchasing option is MOST cost-effective for this scenario?', '["Utilize Amazon EC2 Spot Instances for the entire batch processing fleet.","Purchase Amazon EC2 Reserved Instances with a 1-year No Upfront payment option.","Implement EC2 Savings Plans for Compute, committing to a specific hourly spend.","Run On-Demand Amazon EC2 instances and use Auto Scaling to manage capacity."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for fault-tolerant, flexible workloads. Amazon EC2 Spot Instances allow you to bid on unused EC2 capacity, offering significant discounts (up to 90% off On-Demand prices) in exchange for the possibility of interruptions. Since the workload can tolerate interruptions and has flexible timing, Spot Instances are ideal for minimizing costs. Option B (incorrect) is suitable for steady-state, predictable workloads over a 1-3 year term, not for flexible, interruptible batch jobs. Using Reserved Instances for variable or unpredictable workloads is an anti-pattern [ap-4.2-001]. Option C (incorrect) offers flexibility across instance families and regions, but still requires a commitment to a consistent spend, which might not be fully utilized by an intermittent batch workload, and the discount is typically less than Spot Instances. Option D (incorrect) uses On-Demand instances, which are the most expensive purchasing option and do not provide the cost savings required for this scenario, even with Auto Scaling for capacity management.', 21, 'm_21_2', 1, NULL, NULL),
  ('mock_18_all_1774925287644', 'A development team frequently provisions Amazon EC2 instances for testing new features. These instances are typically used during business hours (9 AM to 5 PM, Monday to Friday) and remain idle outside of these times. The company wants to reduce costs associated with these development environments. Which approach offers the LEAST operational overhead for cost optimization?', '["Manually start and stop EC2 instances at the beginning and end of each workday.","Implement an AWS Lambda function triggered by Amazon CloudWatch Events to automatically start and stop EC2 instances based on a schedule.","Configure EC2 Auto Scaling groups to scale instances down to zero outside of business hours.","Purchase EC2 Reserved Instances for the development environment instances to reduce hourly costs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the least operational overhead for managing the lifecycle of development instances. An AWS Lambda function triggered by Amazon CloudWatch Events (now Amazon EventBridge) can automate the start and stop schedule, ensuring instances only run when needed. This eliminates manual intervention and significantly reduces costs for idle resources. Option A (incorrect) requires constant manual effort, which is high operational overhead and prone to human error, directly contradicting the ''LEAST operational overhead'' constraint. Running idle development environments 24/7 is an anti-pattern [ap-4.2-002]. Option C (incorrect) is designed for scaling based on demand, not for fixed schedules, and configuring it to scale to zero might introduce complexity for development environments that need specific configurations to persist. Option D (incorrect) is not suitable for intermittent workloads. Reserved Instances are for steady-state, predictable usage and would still incur costs during idle periods, making it an ineffective cost-saving measure for this scenario.', 21, 'm_21_2', 2, NULL, NULL),
  ('mock_18_all_1774925287644', 'A financial analytics firm runs a critical, long-running data processing application on Amazon EC2 instances. This application requires consistent performance and operates 24/7 with a predictable workload over the next three years. The firm needs to minimize compute costs while ensuring stability. Which EC2 purchasing option is MOST cost-effective for this application?', '["Utilize Amazon EC2 Spot Instances with a maximum price bid for the workload.","Run On-Demand Amazon EC2 instances and leverage Auto Scaling for capacity management.","Purchase Amazon EC2 Reserved Instances for a 3-year term with an All Upfront payment.","Implement AWS Savings Plans for Compute, committing to a flexible hourly spend."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective solution for a critical, long-running application with a predictable workload over a multi-year period. Purchasing Amazon EC2 Reserved Instances with a 3-year All Upfront payment offers the deepest discounts compared to other purchasing options for consistent usage. Option A (incorrect) is unsuitable for a critical, long-running application that cannot tolerate interruptions. Spot Instances are designed for fault-tolerant, flexible workloads. Option B (incorrect) uses On-Demand instances, which are the most expensive option and do not provide the significant cost savings needed for a predictable 24/7 workload. Option D (incorrect) offers flexibility across instance types and regions, and generally provides better discounts than On-Demand, but a 3-year All Upfront Reserved Instance typically provides a deeper discount for a truly steady-state, specific instance type commitment.', 21, 'm_21_2', 3, NULL, NULL),
  ('mock_18_all_1774925287644', 'A startup is developing a new serverless application that processes user requests. Each request involves a small amount of computation (under 10 seconds) and is highly variable, with unpredictable spikes in traffic throughout the day. The company wants to ensure high scalability and pay only for the compute resources consumed, minimizing idle costs. Which compute service is the MOST cost-effective choice?', '["Deploy the application on Amazon EC2 instances within an Auto Scaling group.","Utilize AWS Fargate to run containers for the application.","Implement AWS Lambda functions to handle each user request.","Provision Amazon EC2 Reserved Instances for anticipated peak loads."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective solution for highly variable, intermittent, and short-duration compute tasks. AWS Lambda is a serverless compute service that automatically scales and charges only for the compute time consumed, measured in milliseconds, eliminating idle costs. Option A (incorrect) would incur costs for EC2 instances even when idle, and Auto Scaling adds operational overhead compared to a fully serverless solution. Option B (incorrect) is a serverless compute engine for containers, which is more cost-effective than EC2 for containerized workloads, but for very short, event-driven functions, AWS Lambda is typically more granular and cost-efficient. Option D (incorrect) is designed for predictable, long-term workloads and would result in significant overspending for an unpredictable, spiky application, as Reserved Instances assume steady-state usage.', 21, 'm_21_2', 4, NULL, NULL),
  ('mock_18_all_1774925287644', 'A software company is migrating its existing Java-based microservices to AWS. The microservices are CPU-intensive but compatible with ARM architecture. The company aims to reduce its compute costs significantly without compromising performance. Which Amazon EC2 instance family should the Solutions Architect recommend for the MOST cost-effective solution?', '["C6g instances, which are powered by AWS Graviton2 processors.","M5 instances, which are general-purpose instances powered by Intel processors.","R6i instances, which are memory-optimized instances powered by Intel processors.","T3 instances, which are burstable performance instances powered by Intel processors."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective choice for compatible workloads. C6g instances are powered by AWS Graviton2 processors (ARM-based) and are designed to deliver up to 40% better price/performance over comparable x86-based instances for a wide range of workloads, including CPU-intensive microservices. Not considering Graviton (ARM) instances for compatible workloads is an anti-pattern [ap-4.2-004]. Option B (incorrect) and Option C (incorrect) are x86-based instances, which would not provide the same price/performance benefits as Graviton2 for compatible workloads. Option D (incorrect) T3 instances are burstable and generally not suitable for consistently CPU-intensive applications, as they can incur additional costs if they burst beyond their baseline for extended periods.', 21, 'm_21_2', 5, NULL, NULL);

