-- Module: m_21_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A data analytics startup uses an Amazon RDS for PostgreSQL database for its internal dashboards. The database experiences highly variable usage patterns, with peak activity during business hours and minimal usage overnight and on weekends. The company wants to optimize database costs by paying only for what it uses, without manual scaling. Which Amazon Aurora deployment option is MOST cost-effective?', '["Migrate to Amazon RDS for PostgreSQL with a Multi-AZ deployment and provisioned capacity.","Migrate to Amazon Aurora Serverless v2 for PostgreSQL.","Migrate to Amazon DynamoDB with On-Demand capacity mode.","Migrate to Amazon RDS for PostgreSQL with a Single-AZ deployment and provisioned capacity."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective solution for highly variable and intermittent database workloads. Amazon Aurora Serverless v2 scales capacity in fine-grained increments and can scale down to minimal ACUs (Aurora Capacity Units) during idle periods, ensuring the company only pays for the capacity it consumes. This avoids paying for unused provisioned capacity, which is an anti-pattern [ap-4.3-003]. Option A (incorrect) uses provisioned capacity and Multi-AZ, which is designed for high availability and consistent workloads, not for cost optimization of variable usage, and would incur costs even during idle times. Option C (incorrect) is a NoSQL database, which might not be suitable for a relational workload like internal dashboards without significant re-architecture, and while On-Demand is cost-effective for variable NoSQL, it''s not the right database type here. Option D (incorrect) uses provisioned capacity, meaning costs would still be incurred during idle periods, making it less cost-effective than Aurora Serverless v2 for variable workloads.', 21, 'm_21_3', 6, NULL, NULL),
  ('mock_18_all_1774925287644', 'A gaming company uses Amazon DynamoDB to store player profiles. The access patterns to these profiles are highly unpredictable, with sudden spikes during game launches or promotional events. The company wants to ensure that the database can handle any traffic volume without throttling, while also minimizing costs during low-traffic periods. Which DynamoDB capacity mode is MOST cost-effective?', '["Utilize Provisioned capacity mode with Auto Scaling enabled for read and write capacity units.","Implement a caching layer using Amazon ElastiCache in front of DynamoDB.","Configure DynamoDB to use On-Demand capacity mode.","Set up DynamoDB Global Tables to distribute traffic across multiple Regions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective solution for unpredictable traffic patterns in Amazon DynamoDB. On-Demand capacity mode automatically scales to accommodate workloads and charges only for the read and write requests actually performed, eliminating the need for capacity planning and preventing throttling during spikes. Using provisioned capacity for DynamoDB with unpredictable traffic is an anti-pattern [ap-4.3-002]. Option A (incorrect) requires upfront capacity planning and, even with Auto Scaling, can still lead to over-provisioning during low periods or throttling during sudden, sharp spikes while the scaling adjusts. Option B (incorrect) can reduce read costs and improve performance for frequently accessed data, but it doesn''t address the underlying cost of DynamoDB capacity for unpredictable writes or initial reads. Option D (incorrect) is for multi-Region replication and high availability, not primarily for cost optimization of unpredictable single-Region traffic.', 21, 'm_21_3', 7, NULL, NULL),
  ('mock_18_all_1774925287644', 'A software development company maintains a non-critical Amazon RDS for MySQL database for its internal testing environment. This database is used intermittently by developers and does not require high availability, but cost optimization is a key concern. The current setup uses a Multi-AZ deployment. Which configuration change would be MOST cost-effective?', '["Change the Amazon RDS for MySQL deployment from Multi-AZ to Single-AZ.","Migrate the database to Amazon Aurora Serverless v2 with Multi-AZ enabled.","Scale down the Amazon RDS instance to the smallest available instance type.","Implement Amazon RDS Proxy to manage database connections."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective change. For a non-critical development database that does not require high availability, switching from a Multi-AZ deployment to a Single-AZ deployment will reduce costs by eliminating the synchronous standby instance. Running RDS Multi-AZ for non-critical development databases is an anti-pattern [ap-4.3-001]. Option B (incorrect) would be more expensive as Aurora Serverless v2, especially with Multi-AZ, is designed for production-grade, highly scalable workloads, and while it scales down, a Single-AZ RDS instance for a non-critical test environment is typically cheaper. Option C (incorrect) scaling down the instance type is a good cost optimization, but it still incurs the cost of the Multi-AZ standby. Changing to Single-AZ provides a more significant immediate cost reduction for this specific scenario. Option D (incorrect) is used to manage database connections and connection pooling, which can reduce load and improve application resilience, but it does not directly reduce the underlying cost of the RDS instance itself.', 21, 'm_21_3', 8, NULL, NULL),
  ('mock_18_all_1774925287644', 'A global news website experiences frequent, high-volume read requests for breaking news articles, which are stored in an Amazon RDS for PostgreSQL database. To improve response times and reduce the load on the database, the company wants to implement a caching solution for these frequently accessed articles. Which service is MOST suitable for this purpose?', '["Utilize Amazon S3 for storing cached articles.","Deploy Amazon ElastiCache for Redis to cache the articles.","Implement Amazon DynamoDB Accelerator (DAX) in front of the RDS database.","Use an Amazon RDS Read Replica to serve cached content."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable service for caching frequently accessed data to improve response times and reduce database load. Amazon ElastiCache for Redis is an in-memory data store that provides sub-millisecond latency for retrieving cached items, making it ideal for high-volume read requests like news articles. Option A (incorrect) Amazon S3 is object storage and while it can store data, it''s not designed for low-latency, in-memory caching of database queries. Option C (incorrect) Amazon DynamoDB Accelerator (DAX) is specifically designed for DynamoDB to provide microsecond latency for read-heavy workloads, but it is not compatible with Amazon RDS for PostgreSQL. Option D (incorrect) an Amazon RDS Read Replica offloads read traffic from the primary database, but it is still a database instance and does not provide the same ultra-low latency caching benefits as an in-memory cache like ElastiCache.', 21, 'm_21_3', 9, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_21_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A company hosts a web application on Amazon EC2 instances in a private subnet. These instances need to securely download software updates from Amazon S3 buckets without traversing the public internet or incurring NAT Gateway data processing charges. Which networking solution is the MOST cost-effective for this requirement?', '["Configure an Amazon EC2 NAT Instance in a public subnet to route S3 traffic.","Route all S3 traffic through an AWS Transit Gateway connected to the VPC.","Create an Amazon S3 Gateway VPC Endpoint in the VPC.","Set up an Amazon EC2 NAT Gateway in a public subnet to route S3 traffic."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective solution. An Amazon S3 Gateway VPC Endpoint allows instances in private subnets to access Amazon S3 directly, using private IP addresses, without requiring an internet gateway, NAT device, or VPN connection. Gateway VPC endpoints for S3 are free and keep traffic within the AWS network, directly addressing the constraint of avoiding NAT Gateway charges. Using NAT Gateway for traffic that could go through VPC endpoints is an anti-pattern [ap-4.4-001]. Option A (incorrect) and Option D (incorrect) would both incur costs (per hour and per GB processed for NAT Gateway, or instance costs for NAT Instance) and are unnecessary for S3 access, as S3 Gateway Endpoints are free. Option B (incorrect) AWS Transit Gateway is used for centralizing network connectivity between many VPCs and on-premises networks; while it can route traffic, it''s an overkill and more expensive solution for simply accessing S3 within a single VPC.', 21, 'm_21_4', 10, NULL, NULL),
  ('mock_18_all_1774925287644', 'A multinational corporation has two separate Amazon VPCs in different AWS Regions: `us-east-1` and `eu-west-1`. Applications in both VPCs need to communicate privately and securely, exchanging large volumes of data. The company wants to minimize data transfer costs and latency for this inter-Region communication. Which networking solution is MOST appropriate?', '["Route traffic between the VPCs over the public internet using Elastic IP addresses.","Establish an AWS Transit Gateway and connect both VPCs to it.","Configure a site-to-site VPN connection between the two VPCs.","Set up VPC peering between the `us-east-1` and `eu-west-1` VPCs."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate solution for private, secure, and cost-effective communication between two VPCs in different AWS Regions. VPC peering allows direct network routing between two VPCs using private IP addresses, leveraging the AWS global backbone, which offers lower latency and often more cost-effective data transfer than public internet routing. Routing inter-Region traffic through the public internet instead of using VPC peering or Transit Gateway is an anti-pattern [ap-4.4-002]. Option A (incorrect) would incur higher data transfer costs for egress to the public internet, introduce higher latency, and is less secure than private connectivity. Option B (incorrect) AWS Transit Gateway is designed for connecting a large number of VPCs and on-premises networks centrally, which would be an over-engineered and more expensive solution for just two VPCs. Option C (incorrect) a site-to-site VPN connection would provide secure communication but typically has higher latency and lower bandwidth compared to VPC peering over the AWS backbone, and also incurs hourly charges for the VPN connection.', 21, 'm_21_4', 11, NULL, NULL),
  ('mock_18_all_1774925287644', 'A small development team uses Amazon EC2 instances in a private subnet to run daily automated tests. These instances occasionally need to access external APIs on the internet. The team wants a cost-effective solution for outbound internet access, considering their low and infrequent data transfer volume. Which approach is MOST cost-effective?', '["Deploy a single Amazon EC2 NAT Instance in a public subnet.","Configure an Amazon EC2 NAT Gateway in a public subnet.","Use an Internet Gateway attached directly to the private subnet.","Implement AWS PrivateLink for each external API endpoint."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for outbound internet access for a small development team with low and infrequent data transfer volumes. A single Amazon EC2 NAT Instance can be a cheaper alternative to a NAT Gateway for small-scale, non-critical workloads, as you only pay for the EC2 instance and associated data transfer, avoiding the higher hourly and per-GB processing charges of a NAT Gateway. Option B (incorrect) Amazon EC2 NAT Gateway is a highly available and scalable managed service, but it is more expensive due to its hourly charge and per-GB data processing fees, making it less cost-effective for low-volume, non-critical use cases. Option C (incorrect) an Internet Gateway cannot be attached directly to a private subnet; instances in a private subnet require a NAT device to access the internet. Option D (incorrect) AWS PrivateLink provides private connectivity to specific services, not general internet access, and would be cost-prohibitive for accessing multiple external APIs.', 21, 'm_21_4', 12, NULL, NULL),
  ('mock_18_all_1774925287644', 'A SaaS provider hosts its application in a VPC and offers a service to its customers. Customers, who also have their infrastructure on AWS, need to privately and securely access the SaaS provider''s service without exposing traffic to the public internet or peering their entire VPCs. The SaaS provider wants to offer this connectivity with minimal operational overhead for both parties. Which solution is MOST appropriate?', '["Set up a VPC peering connection between each customer''s VPC and the SaaS provider''s VPC.","Utilize AWS PrivateLink to expose the SaaS service endpoint to customer VPCs.","Configure a Site-to-Site VPN connection between each customer''s VPC and the SaaS provider''s VPC.","Deploy an Application Load Balancer in the SaaS provider''s public subnet and allow customer access via public IPs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate solution. AWS PrivateLink allows customers to connect to services hosted in other VPCs as if they were in their own VPC, using private IP addresses. It eliminates the need for an Internet Gateway, NAT device, VPN connection, or VPC peering, providing secure, private connectivity with minimal operational overhead for both the service provider and consumers. Option A (incorrect) VPC peering would require managing many-to-many peering connections for each customer, which becomes complex and difficult to scale as the number of customers grows. It also exposes the entire peered VPCs'' routing tables, which might not be desired for security reasons. Option C (incorrect) a Site-to-Site VPN connection would provide private connectivity but is more complex to set up and manage for multiple customers compared to PrivateLink, and incurs hourly charges. Option D (incorrect) exposing the service via a public Application Load Balancer would violate the requirement for private and secure access without traversing the public internet.', 21, 'm_21_4', 13, NULL, NULL),
  ('mock_18_all_1774925287644', 'A company has a multi-tier application where the web servers are in a public subnet and the application servers are in a private subnet, all within the same AWS Region but across different Availability Zones (AZs). The application servers frequently communicate with a database in another private subnet, also across different AZs. The company wants to minimize data transfer costs within the VPC. Which design principle should be followed?', '["Ensure all communication between application tiers uses public IP addresses to avoid cross-AZ charges.","Place all application servers and database instances in the same Availability Zone to eliminate cross-AZ data transfer.","Design the application to keep data transfer between instances within the same Availability Zone whenever possible.","Utilize an AWS Transit Gateway to route all inter-AZ traffic efficiently."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the principle to follow for minimizing data transfer costs within a VPC. Data transfer between Availability Zones within the same AWS Region incurs charges. By designing the application to keep communication between instances within the same Availability Zone when possible (e.g., placing an application server and its primary database replica in the same AZ), these cross-AZ data transfer costs can be minimized. Option A (incorrect) using public IP addresses for communication between instances within the same VPC, even across AZs, would incur higher data transfer costs (internet egress) and is less secure than private IP communication. Option B (incorrect) placing all resources in a single Availability Zone would eliminate cross-AZ data transfer costs but would severely compromise the application''s high availability and fault tolerance, which is a critical best practice. Option D (incorrect) AWS Transit Gateway is for connecting multiple VPCs and on-premises networks, not for optimizing data transfer within a single VPC across AZs. It would add unnecessary cost and complexity.', 21, 'm_21_4', 14, NULL, NULL);

