INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_18_all_1774925287644', 'A research institution stores petabytes of scientific data in Amazon S3. The data is accessed frequently for the first 30 days after upload, then access patterns become unpredictable for the next 90 days, and finally, the data is rarely accessed but must be retained for compliance for 5 years. The institution wants to optimize storage costs while ensuring data availability. Which S3 storage strategy is MOST cost-effective?', '["Store all data in Amazon S3 Standard and manually move it to Amazon S3 Glacier after 120 days.","Use Amazon S3 Standard for the first 30 days, then transition to Amazon S3 Standard-IA for 90 days, and finally to Amazon S3 Glacier Deep Archive.","Store all data in Amazon S3 One Zone-IA for the first 120 days, then transition to Amazon S3 Glacier.","Use Amazon S3 Standard for the first 30 days, then transition to Amazon S3 Intelligent-Tiering for 90 days, and finally to Amazon S3 Glacier Flexible Retrieval."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most cost-effective strategy for this scenario. Amazon S3 Standard is appropriate for frequently accessed data (first 30 days). For the next 90 days, when access patterns are unpredictable, Amazon S3 Intelligent-Tiering automatically moves objects between frequent and infrequent access tiers without retrieval fees, optimizing costs. Not enabling S3 Intelligent-Tiering for unpredictable access patterns is an anti-pattern [ap-4.1-003]. Finally, for rarely accessed data retained for 5 years, Amazon S3 Glacier Flexible Retrieval (formerly Glacier) is suitable for long-term archiving with flexible retrieval options. Option A (incorrect) requires manual intervention, which is not scalable or efficient, and keeping all S3 data in Standard tier without lifecycle policies is an anti-pattern [ap-4.1-001]. Option B (incorrect) uses S3 Standard-IA for the unpredictable phase, which incurs retrieval fees if data becomes more frequently accessed, making Intelligent-Tiering more suitable. Option C (incorrect) S3 One Zone-IA is not recommended for data that needs high durability and availability across AZs, as it only stores data in a single AZ, and it doesn''t handle unpredictable access patterns as efficiently as Intelligent-Tiering.', 21, 'm_21_1', 15, NULL, NULL),
  ('mock_18_all_1774925287644', 'A media archiving company needs to store large video files that are frequently accessed immediately after upload for quality checks, but then become infrequently accessed over time. After 90 days, the files are rarely accessed but must be retained for 7 years. The company wants to automate storage tier transitions to minimize costs. Which Amazon S3 lifecycle policy configuration is MOST cost-effective?', '["Transition objects to Amazon S3 Standard-IA after 30 days, then to Amazon S3 Glacier Flexible Retrieval after 90 days.","Transition objects to Amazon S3 Intelligent-Tiering after 60 days, then to Amazon S3 Glacier Deep Archive after 180 days.","Transition objects to Amazon S3 One Zone-IA after 30 days, then to Amazon S3 Glacier Instant Retrieval after 180 days.","Store all objects in Amazon S3 Standard for the entire 7-year retention period."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective lifecycle policy. For data that becomes infrequently accessed after an initial period, transitioning to Amazon S3 Standard-IA after 30 days is appropriate. For data that is rarely accessed but needs long-term retention, transitioning to Amazon S3 Glacier Flexible Retrieval (formerly Glacier) after 90 days (60 days after the Standard-IA transition) is suitable, as it offers significant cost savings for archival storage. Keeping all S3 data in Standard tier without lifecycle policies is an anti-pattern [ap-4.1-001]. Option B (incorrect) while Intelligent-Tiering is good for unpredictable access, the scenario describes a clear pattern of decreasing access, making direct transitions more predictable for cost. Glacier Deep Archive might be too slow for ''rarely accessed'' if retrieval flexibility is needed. Option C (incorrect) S3 One Zone-IA is less durable and available than Standard-IA, and might not be suitable for critical media archives. Option D (incorrect) storing all objects in S3 Standard for 7 years would be significantly more expensive than utilizing lifecycle policies to transition to lower-cost tiers.', 21, 'm_21_1', 16, NULL, NULL),
  ('mock_18_all_1774925287644', 'A data processing application running on Amazon EC2 instances requires block storage with a baseline performance of 4,000 IOPS and 200 MiB/s throughput. The application''s workload is consistent, and the company wants to minimize storage costs. Which Amazon EBS volume type is MOST cost-effective for this requirement?', '["Provisioned IOPS SSD (io2) volume type.","General Purpose SSD (gp3) volume type.","General Purpose SSD (gp2) volume type.","Throughput Optimized HDD (st1) volume type."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective EBS volume type for this requirement. General Purpose SSD (gp3) volumes provide a baseline performance of 3,000 IOPS and 125 MiB/s throughput at no extra cost, and you can provision additional IOPS (up to 16,000) and throughput (up to 1,000 MiB/s) independently for a lower cost than io2. For 4,000 IOPS and 200 MiB/s, gp3 can meet the requirement cost-effectively. Using Provisioned IOPS (io2) EBS when gp3 meets the IOPS requirement is an anti-pattern [ap-4.1-002]. Option A (incorrect) Provisioned IOPS SSD (io2) volumes are designed for critical, high-performance applications requiring sustained IOPS beyond what gp3 can provide, and they are significantly more expensive than gp3 for the specified baseline. Option C (incorrect) General Purpose SSD (gp2) volumes scale performance with size, and to achieve 4,000 IOPS, a larger and potentially more expensive volume would be required than a gp3 volume provisioned for the same IOPS. Option D (incorrect) Throughput Optimized HDD (st1) volumes are designed for frequently accessed, throughput-intensive workloads, but they are HDD-based and do not provide the low-latency IOPS performance of SSDs required by the application.', 21, 'm_21_1', 17, NULL, NULL),
  ('mock_18_all_1774925287644', 'A software development team needs a shared file system for their Amazon EC2 instances to store project files, code repositories, and build artifacts. The file system must be accessible concurrently by multiple EC2 instances, support standard file system protocols, and scale automatically without manual intervention. The team prioritizes ease of management and cost-effectiveness. Which AWS storage service is MOST suitable?', '["Store files on individual Amazon EBS volumes attached to each EC2 instance.","Utilize Amazon S3 buckets for storing all project files and artifacts.","Deploy Amazon EFS (Elastic File System) for shared file storage.","Use Amazon S3 Glacier Deep Archive for long-term storage of project files."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable service. Amazon EFS provides a simple, scalable, elastic file system for use with AWS Cloud services and on-premises resources. It is designed to be accessible concurrently by thousands of Amazon EC2 instances, supporting standard file system protocols (NFSv4), and scales automatically up or down as you add and remove files, making it highly cost-effective and easy to manage for shared file storage. Option A (incorrect) Amazon EBS volumes are block storage, designed for single-instance attachment, and do not support concurrent access by multiple EC2 instances, making them unsuitable for a shared file system. Option B (incorrect) Amazon S3 is object storage, not a file system. While it can store files, it does not support standard file system protocols or concurrent mounting by multiple EC2 instances in the same way EFS does. Storing infrequently accessed data in EBS instead of S3 is an anti-pattern [ap-4.1-004], but this question is about shared file system, not infrequently accessed data. Option D (incorrect) Amazon S3 Glacier Deep Archive is for long-term, archival storage with retrieval times in hours, making it entirely unsuitable for active project files and build artifacts that require frequent access.', 21, 'm_21_1', 18, NULL, NULL);

